class Solution:
    def longestArithSeqLength(self, nums: list[int]) -> int:
        n = len(nums)
        best = 2
        for i in range(n):
            for j in range(i + 1, n):
                diff = nums[j] - nums[i]
                length = 2
                last = nums[j]
                for t in range(j + 1, n):
                    if nums[t] - last == diff:
                        length += 1
                        last = nums[t]
                best = max(best, length)
        return best

