class Solution:
    def longestArithSeqLength(self, nums: list[int]) -> int:
        n = len(nums)
        dp = [{} for _ in range(n)]
        best = 2
        for i in range(n):
            for j in range(i):
                diff = nums[i] - nums[j]
                dp[i][diff] = max(dp[i].get(diff, 1), dp[j].get(diff, 1) + 1)
                best = max(best, dp[i][diff])
        return best

